};
for (let i=0; i<items.length; i++) {
  const keys=Object.keys(items[i].binary ?? {});
  if (keys.length!==1) throw new Error('Envie exatamente um arquivo de despesa.');
  const key=keys[0], meta=items[i].binary[key];
  const bytes=await this.helpers.getBinaryDataBuffer(i,key);
  if (!bytes.length || bytes.length>20*1024*1024) throw new Error('O arquivo deve ter entre 1 byte e 20 MB.');
  let mime=null;
  if (bytes.length>=5 && bytes.toString('ascii',0,5)==='%PDF-') mime='application/pdf';
  else if (bytes.length>=3 && bytes[0]===0xff && bytes[1]===0xd8 && bytes[2]===0xff) mime='image/jpeg';
  else if (bytes.length>=8 && bytes.subarray(0,8).toString('hex')==='89504e470d0a1a0a') mime='image/png';
  else if (bytes.length>=12 && bytes.toString('ascii',0,4)==='RIFF' && bytes.toString('ascii',8,12)==='WEBP') mime='image/webp';
  if (!mime) throw new Error('Formato inválido. Envie PDF, JPG, PNG ou WebP.');
  const base64=bytes.toString('base64');
  const content=mime==='application/pdf'
    ? {type:'input_file',filename:meta.fileName||'despesa.pdf',file_data:'data:application/pdf;base64,'+base64}
    : {type:'input_image',image_url:'data:'+mime+';base64,'+base64,detail:'high'};
